sys_script_client.script:
function onLoad() {

    var Loader = g_scratchpad.created_time;
	//Loader = True/False.  If True, time < 1 min.   If false time > 1 min.
    if (Loader) {
        //Show the loading dialog immediately as the form loads
        var loadingDialog = new GlideModal("dialog_loading", true);
        loadingDialog.setPreference('table', 'loading');
        loadingDialog.setTitle('Loading...'); //Set the loading dialog title here...
        loadingDialog.render();


        var count = 0;

        var interval = setInterval(myTimer, 1000);
    }

    function myTimer() {
        count++;
        if (count == 10) { // Wait for 10 sec in case of infinite loop and then exit.
            clearInterval(interval);
            loadingDialog.destroy();     
        }
        var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        ga.addParam('sysparm_name', 'DisplayLoader');
        ga.addParam('sysparm_bulkid', g_form.getUniqueValue());
        ga.getXMLAnswer(stopLoader);
    }

    function stopLoader(answer) {
        var ans = answer;
        if (ans) {
            clearInterval(interval);
            loadingDialog.destroy();
        }
    }
}
